user_message:
Compare the typed predicate candidates against the existing registry.
Candidate predicates:
[
  {
    "name": "IS_PLAN",
    "definition": "The reasoning explicitly expresses an intended future action or an ordered approach that the agent intends to carry out before those actions occur.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text expressing the intended future action or sequence of steps."
      }
    ],
    "assertion_conditions": [
      "The reasoning uses prospective framing to identify at least one action or step the agent intends to take.",
      "The stated intent precedes the corresponding action rather than reporting a completed one."
    ],
    "exclusion_conditions": [
      "The reasoning only reports actions already completed and their results.",
      "The reasoning only restates the task description without committing to an approach the agent will take."
    ]
  },
  {
    "name": "IDENTIFIES_UNDERSPECIFIED_REQUIREMENT",
    "definition": "The reasoning detects an ambiguity, gap, or unstated edge case in the given requirements, weighs competing interpretations or their risks, and commits to one interpretation before implementing.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that flags the ambiguity and settles on an interpretation."
      }
    ],
    "assertion_conditions": [
      "The reasoning names a specific requirement that is ambiguous or underspecified.",
      "The reasoning considers at least two candidate interpretations or explicitly weighs the risk of each option.",
      "The reasoning commits to a chosen interpretation that later implementation follows."
    ],
    "exclusion_conditions": [
      "The reasoning merely paraphrases the requirements without identifying any ambiguity or gap.",
      "An ambiguity is mentioned but no interpretation is chosen and no alternatives are weighed.",
      "The reasoning describes a decision that is fully determined by explicit requirements."
    ]
  },
  {
    "name": "GROUNDS_DECISION_IN_OBSERVATION",
    "definition": "The reasoning adopts or justifies a specific course of action (which approach, tool, or interpretation to use) using identifiable content of an observation as supporting evidence.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning stating the decision and the basis for it."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation supplying the evidence on which the decision rests."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a decision about what to do next.",
      "The reasoning relies on specific facts reported in the observation as the reason for that decision.",
      "The observation content logically bears on the chosen course of action."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats or summarizes the observation without drawing a decision from it.",
      "The observation is unrelated to the stated decision or provides no identifiable support.",
      "The decision is presented with no reference to observed facts."
    ]
  },
  {
    "name": "PROBE_RESOLVES_STATED_UNCERTAINTY",
    "definition": "An action is directed at resolving a specific uncertainty or unverified claim stated in reasoning, and the resulting observation supplies interpretable evidence about that uncertainty.",
    "parameters": [
      {
        "name": "uncertainty_reasoning",
        "type": "reasoning",
        "description": "The reasoning identifying the unknown state or unverified claim."
      },
      {
        "name": "probe_action",
        "type": "action",
        "description": "The action that targets the unknown state or claim."
      },
      {
        "name": "probe_result",
        "type": "observation",
        "description": "The observation reporting the outcome relevant to that uncertainty."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a specific unknown property, capability, or unverified claim.",
      "The probe action is designed to reveal the value or status of that property or claim.",
      "The resulting observation contains a result that can be interpreted with respect to the identified uncertainty."
    ],
    "exclusion_conditions": [
      "The action is routine execution unrelated to any stated uncertainty.",
      "The observation does not address the property or claim being examined.",
      "No identifiable uncertainty or claim motivates the action."
    ]
  },
  {
    "name": "DIAGNOSES_FAILURE_CAUSE",
    "definition": "The reasoning explains why an observed failure or error occurred by naming a specific cause, rather than merely restating that the failure happened.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning containing the causal explanation."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation reporting the failure or error being explained."
      }
    ],
    "assertion_conditions": [
      "The observation reports an error, rejection, or failed outcome.",
      "The reasoning names a specific cause for that failure.",
      "The causal attribution is connected to the content of the observation."
    ],
    "exclusion_conditions": [
      "The reasoning only repeats the error message or notes that something failed without explaining why.",
      "The reasoning attributes the failure to a cause that is not supported by the observation.",
      "No failure is reported in the corresponding observation."
    ]
  },
  {
    "name": "RETRIES_WITH_CORRECTED_ACTION",
    "definition": "After a failed attempt, the reasoning identifies a correctable defect in that attempt, and a subsequent action repeats the same operation with the defect corrected.",
    "parameters": [
      {
        "name": "failed_observation",
        "type": "observation",
        "description": "The observation reporting the failure of the prior attempt."
      },
      {
        "name": "corrective_reasoning",
        "type": "reasoning",
        "description": "The reasoning naming the defect and the intended correction."
      },
      {
        "name": "retry_action",
        "type": "action",
        "description": "The action repeating the operation with the correction applied."
      }
    ],
    "assertion_conditions": [
      "The observation shows that the preceding attempt failed.",
      "The reasoning identifies the specific defect to be fixed and indicates the operation will be attempted again.",
      "The retry action performs the same operation with the identified defect corrected."
    ],
    "exclusion_conditions": [
      "The reasoning abandons the operation instead of correcting and repeating it.",
      "The retry action does not address the defect named in the reasoning.",
      "No prior failure is present in the trajectory."
    ]
  },
  {
    "name": "REPLACES_UNAVAILABLE_MEANS",
    "definition": "An observation shows that a preferred tool or capability is unavailable, and the reasoning selects a functionally different means to accomplish the same goal, which the subsequent action then performs.",
    "parameters": [
      {
        "name": "unavailability_observation",
        "type": "observation",
        "description": "The observation showing that the preferred tool or capability cannot be used."
      },
      {
        "name": "substitution_reasoning",
        "type": "reasoning",
        "description": "The reasoning stating the substitution and its equivalent purpose."
      },
      {
        "name": "alternative_action",
        "type": "action",
        "description": "The action carrying out the substituted means."
      }
    ],
    "assertion_conditions": [
      "The observation shows a tool or capability is absent or nonfunctional.",
      "The reasoning states that the preferred means cannot be used and names an alternative means for the same purpose.",
      "The alternative action implements that alternative means."
    ],
    "exclusion_conditions": [
      "The failure stems from malformed arguments or inputs rather than an unavailable capability.",
      "The subsequent action reuses the same unavailable tool.",
      "The alternative does not serve the same goal as the original means."
    ]
  },
  {
    "name": "ATTRIBUTES_FAILURE_TO_TEST_INSTRUMENT",
    "definition": "The reasoning determines that an observed error originates in the checking procedure or its own inputs rather than in the artifact under test, leaving the artifact's behavior unrefuted.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning localizing the failure to the checking procedure."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation reporting the error raised during verification."
      }
    ],
    "assertion_conditions": [
      "The observation reports an error that occurred while a verification procedure was running.",
      "The reasoning locates the cause in the checking procedure or its inputs.",
      "The reasoning explicitly distinguishes that cause from the behavior of the artifact under test."
    ],
    "exclusion_conditions": [
      "The reasoning attributes the error to the artifact under test.",
      "The reasoning re-runs the check without attributing the error to either side.",
      "No verification error is reported."
    ]
  },
  {
    "name": "CONFIRMS_REQUIREMENTS_SATISFIED",
    "definition": "The reasoning concludes that specified requirements have been satisfied, resting that conclusion on the collective evidence of one or more observations of executed checks whose results matched expectations.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning drawing the satisfaction conclusion from the collected results."
      },
      {
        "name": "observations",
        "type": "observation[]",
        "description": "The observations of executed checks that jointly support the conclusion; support is collective, not alternative."
      }
    ],
    "assertion_conditions": [
      "The reasoning refers to outcomes of executed checks and compares them with expected behavior.",
      "The reasoning explicitly concludes that the required behavior has been met.",
      "Each cited observation contributes a result that the conclusion depends on."
    ],
    "exclusion_conditions": [
      "The reasoning only lists raw results without drawing a satisfaction conclusion.",
      "The satisfaction conclusion is asserted with no supporting observed result.",
      "A cited check produced a failing or contradictory result that the reasoning leaves unresolved."
    ]
  }
]

